@@ -321,6 +321,93 @@ const ProductDetail = () => {

   const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
   const variant = useVariant(product);
+
+  // SFCC-194 — Was/Now sale price.
+  //
+  // Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
+  //
+  //   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
+  //   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
+  //                                              variant which lacks tieredPrices reliably)
