+    // Guard matches exactly what the memo reads from the cache: id (for the
+    // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
+    // response that satisfies type.master but lacks either field is not useful — skip it
+    // rather than writing a cache entry that would fall through to the deep-link fallback
+    // one guard too late.
+    if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
+      masterProductRef.current = productResponse;
+    }
+  }, [productResponse]);
+
+  const urlPid = urlParams.get('pid') ?? undefined;
+  const urlColour = urlParams.get('color') ?? undefined;
+  const variantScopedPriceData = useMemo(() => {
+    // Only use the cached master if it belongs to the same product family. If the shopper
+    // navigated from a different PDP (e.g. a "you may also like" link with ?pid= already set),
+    // masterProductRef still holds the previous product's master — its variants[] won't contain
+    // the new product's PIDs, so the filter would return empty and silently bypass the
+    // deep-link fallback below.
+    const cachedMaster = masterProductRef.current;
+    // Positive identity check only — a missing master.masterId is not a match.
+    // The ref is relevant when the current product is the cached master itself, or when
+    // its master.masterId explicitly matches. Anything else (null ref, standard product
+    // with no family, or a different product family) resolves to false so the cached
+    // master is not used and the deep-link fallback path remains effective.
+    const cachedMasterMatchesCurrent =
+      cachedMaster != null &&
+      (product?.id === cachedMaster.id || product?.master?.masterId === cachedMaster.id);
+    const effectiveCachedMaster = cachedMasterMatchesCurrent ? cachedMaster : null;
+
+    // When product is still the master (colour-only selection, no pid) its own variants[] is
+    // the live source. When product has switched to a standalone variant (pid in URL), fall back
+    // to the scoped cached master whose variants[] still carries tieredPrices.
+    const masterVariants = (
+      product?.variants?.length ? product.variants : effectiveCachedMaster?.variants
+    ) as SfccVariant[] | undefined;
+    const masterProduct = product?.variants?.length ? product : effectiveCachedMaster;
+
+    // Deep-link fallback: user arrived with ?pid= already set on a fresh page load, so the
+    // master product was never fetched and masterProductRef is empty. The standalone variant
+    // fetch includes tieredPrices when perPricebook=true, so getPriceData on the variant
+    // itself gives correct Was/Now without needing the master's variants[].
+    if (!masterProduct || !masterVariants?.length) {
+      if ((urlPid || urlColour) && product?.tieredPrices?.length) {
+        return getPriceData(product);
+      }
+      return null;
+    }
+
+    let matchingVariants: SfccVariant[];
+    if (urlPid) {
+      // Exact variant — colour + size fully resolved by SFCC
+      matchingVariants = masterVariants.filter((v) => v.productId === urlPid);
+    } else if (urlColour) {
+      // Colour selected, size not yet — price spans all sizes for this colour
+      matchingVariants = masterVariants.filter((v) => v.variationValues?.color === urlColour);
+    } else {
+      return null; // no selection yet; use the base priceData as-is
+    }
+
+    if (!matchingVariants.length) return null;
+    return getPriceData({ ...masterProduct, variants: matchingVariants });
+    // Re-runs whenever the fetched product changes (standalone variant arrives) or the URL
+    // selection changes — both are the signals that the displayed price must update.
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [urlPid, urlColour, product]);
+
+  // True while keepPreviousData holds stale product data during a variant re-fetch (size
+  // selection). The fetched product id hasn't caught up with the URL yet, so any price
+  // derived from the old product is unreliable — suppress it entirely until the fetch
+  // settles rather than showing a briefly-incorrect Was/Now figure.
+  const isPriceStale = requestedProductId !== product?.id;
+
   // This page uses the `primaryCategoryId` to retrieve the category data. This attribute
   // is only available on `master` products. Since a variation will be loaded once all the
   // attributes are selected (to get the correct inventory values), the category information
@@ -848,7 +935,15 @@ const ProductDetail = () => {
               <ProductView
                 product={product}
                 category={primaryCategory?.parentCategoryTree || []}
-                renderHeader={(headerProps) => <StaticProductHeader {...headerProps} />}
+                renderHeader={(headerProps) => {
+                  return (
+                    <StaticProductHeader
+                      {...headerProps}
+                      priceData={isPriceStale ? null : (variantScopedPriceData ?? headerProps.priceData)}
+                      isPriceLoading={isPriceStale}
+                    />
+                  );
+                }}
                 addToCart={handleAddToCart}
                 addToWishlist={handleAddToWishlist}
                 isProductLoading={isProductLoading}
