+            Was {originalPrice}
+          </chakra.span>
+          <chakra.span __css={styles.nowPrice} data-testid="product-now-price">
+            Now {currentPrice}
+          </chakra.span>
+        </>
+      ) : (
+        currentPrice
+      )}
     </chakra.p>
   );
 };
