  // to the scoped cached master whose variants[] still carries tieredPrices.
  const masterVariants = (
    product?.variants?.length ? product.variants : effectiveCachedMaster?.variants
  ) as SfccVariant[] | undefined;
  const masterProduct = product?.variants?.length ? product : effectiveCachedMaster;

  // Deep-link fallback: user arrived with ?pid= already set on a fresh page load, so the
  // master product was never fetched and masterProductRef is empty. The standalone variant
  // fetch includes tieredPrices when perPricebook=true, so getPriceData on the variant
  // itself gives correct Was/Now without needing the master's variants[].
  if (!masterProduct || !masterVariants?.length) {
    if ((urlPid || urlColour) && product?.tieredPrices?.length) {
      return getPriceData(product);
    }
    return null;
  }

  let matchingVariants: SfccVariant[];
  if (urlPid) {
    // Exact variant — colour + size fully resolved by SFCC
    matchingVariants = masterVariants.filter((v) => v.productId === urlPid);
  } else if (urlColour) {
    // Colour selected, size not yet — price spans all sizes for this colour
    matchingVariants = masterVariants.filter((v) => v.variationValues?.color === urlColour);
  } else {
    return null; // no selection yet; use the base priceData as-is
  }

  if (!matchingVariants.length) return null;
  return getPriceData({ ...masterProduct, variants: matchingVariants });
  // Re-runs whenever the fetched product changes (standalone variant arrives) or the URL
  // selection changes — both are the signals that the displayed price must update.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [urlPid, urlColour, product]);

// True while keepPreviousData holds stale product data during a variant re-fetch (size
// selection). The fetched product id hasn't caught up with the URL yet, so any price
// derived from the old product is unreliable — suppress it entirely until the fetch
// settles rather than showing a briefly-incorrect Was/Now figure.
const isPriceStale = requestedProductId !== product?.id;

// This page uses the `primaryCategoryId` to retrieve the category data. This attribute
// is only available on `master` products. Since a variation will be loaded once all the
// attributes are selected (to get the correct inventory values), the category information
// is overridden. This will allow us to keep the initial category around until a different
// master product is loaded.
useEffect(() => {
  if (category) {
    setPrimaryCategory(category);
  }
}, [category]);

