import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Multi-part recipe for the PDP price — parts: container, wasPrice, nowPrice.
 *
 * Converted from single-part (`useStyleConfig`) to multi-part (`useMultiStyleConfig`) so the
 * Was/Now span colours can be declared here and applied via `__css` in the component, rather
 * than via inline `sx` props. The `sale` variant styles all three parts; `default` only needs
 * the container (the spans never render in that variant).
 *
 * `textStyle` is declared in `baseStyle.container` rather than on the JSX element — if it
 * were on the element, a `sale` variant setting its own composite `textStyle` would be
 * displaced. `toCSSObject` resolves `assignAfter({}, __css, finalBaseStyle, filterUndefined(styleProps), sx)`
 * (dist/index.js lines 204-213), so an element `textStyle=` wins over the recipe — see the
 * original single-part docblock for the full explanation.
 */
export const ZimmProductPrice = {
  parts: ['container', 'wasPrice', 'nowPrice'],

  baseStyle: {
    container: {
      margin: 0,
      color: 'var(--zimm-color-text-default)',
      textStyle: 'price',
    } satisfies SystemStyleObject,
  },

  variants: {
    default: {},

    // PRC-09: Was/Now sale treatment.
    // container → flex row so the two spans sit side-by-side.
    // wasPrice  → secondary text (grey[600] #666666, 5.74:1 on white — WCAG AA).
    //             text.muted (grey[300] #969696, 2.95:1) was the first choice but fails
    //             the 4.5:1 AA threshold; secondary is the next de-emphasised option that passes.
    // nowPrice  → success green for the current sale price.
    sale: {
      container: {
        display: 'flex',
        gap: 'var(--zimm-scale-200)',
        alignItems: 'flex-start',
        whiteSpace: 'nowrap',
      } satisfies SystemStyleObject,
      wasPrice: {
        color: 'var(--zimm-color-text-secondary)',
      } satisfies SystemStyleObject,
      nowPrice: {
        color: 'var(--zimm-color-status-success)',
      } satisfies SystemStyleObject,
    },
  },

  defaultProps: {
    variant: 'default',
  },
};

