import React from 'react';
import { useIntl } from 'react-intl';
import { Skeleton, VStack } from '@salesforce/retail-react-app/app/components/shared/ui';
import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';

/*
 * `app/...`, not `@salesforce/retail-react-app/app/...`, for the two overridden modules below.
 * pwa-kit-dev's OverridesResolverPlugin skips any request whose issuer already lives in
 * `overrides/` (its `isFromExtends` guard), so a base-path import from this file would resolve
 * to the *base* component even in the real app build — the same reason the page's own
 * `product-view` import is relative. `Breadcrumb`, `PromoCallout` and `shared/ui` above have no
 * override, so the base path is the correct one for them.
 */
import type { ProductViewHeaderProps } from 'app/components/product-view';
import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent';
import { selectPdpProductInfo } from '../productInfo';

/**
 * Replaces the title/price block of ProductView's header with the Zimmermann content group.
 *
 * The breadcrumb and promo callout are reproduced from the base header rather than dropped:
 * `renderHeader` replaces the whole header block, and neither of those belongs to SFCC-89
 * (breadcrumb is SFCC-578, badges are SFCC-132/225), so losing them here would be a
 * regression rather than a scope decision.
 *
 * ProductView renders this once per breakpoint, so it stays free of side effects.
 *
 * A component rather than the bare render function it was on the page, so that it can hold
 * `useIntl()` itself — `formatPrice` needs `formatNumber`. components.md exempts `useIntl` from
 * the container/presentational rule because it reads a Provider mounted above the route tree,
 * and this keeps the prop surface exactly `ProductViewHeaderProps`, which passing `formatPrice`
 * in would have widened. `useIntl()` throws without an `IntlProvider`, so anything rendering
 * this must supply one: the app does in the base `_app`, `.storybook/preview.tsx` does for the
 * stories.
 */
export const StaticProductHeader = ({
  name,
  product: headerProduct,
  priceData,
  currency,
  category: headerCategory,
  isProductPartOfBundle,
  isPriceLoading,
}: ProductViewHeaderProps & { isPriceLoading?: boolean }) => {
  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
  // the rule cannot see that. Same suppression, and same reason, as the page's own `useIntl`.
  // eslint-disable-next-line @typescript-eslint/unbound-method
  const { formatNumber } = useIntl();

  // This is the live formatter — the header is the only place a price is rendered. The page
  // declares an identical one, but only to satisfy `selectPdpProductInfo`'s required parameter:
  // it passes `null` for `priceData`, so its copy never executes. Not a leftover of this
  // extraction, and not a value that can drift out of step with this one.
  const formatPrice = (amount: number, priceCurrency: string) =>
    formatNumber(amount, { style: 'currency', currency: priceCurrency });

  const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);

  return (
    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
      {headerCategory && (
        <Skeleton isLoaded={headerCategory} minWidth={64}>
          <Breadcrumb categories={headerCategory} />
        </Skeleton>
      )}

      {/*
       * `minHeight` reserves the name's line box, so the title does not shove the page down
       * when it resolves. SFCC's `Skeleton` baseStyle sets only `borderRadius` and `opacity`,
       * so an empty one measures 0px; the base header avoids that by interpolating the name
       * into a template, which stringifies `undefined` to "undefined" and is therefore always
       * title-height. The value is the name's own line-height: `ZimmProductName` renders at
       * `textStyle: 'heading3'` (declared in its recipe, not as a prop), whose `lineHeight` is
       * `lineHeights['2xs']` (1.125rem / 18px) —
       * the same entry `--zimm-font-lineheight-2xs` is derived from.
       *
       * This reserves ONE line, matching base. A name that wraps still shifts by ~18px, and
       * wrapping is a real case — the design caps the name at 180px inside a 218px column and
       * `zimmProductName/index.stories.tsx` ships a story for it. Reserving two lines would
       * over-reserve for every single-line product and exceed base's own behaviour, which
       * AGENTS.md's minimal-changes rule rules out.
       */}
      <Skeleton isLoaded={Boolean(info)} minHeight="var(--zimm-font-lineheight-2xs)">
        {info && (
          // h2, not h1: the page already emits a screen-reader-only
          // <h1>Product Details</h1>, and the base header this replaces rendered the name
          // as an h2. Changing the outline is SEO's call, not a side-effect of this ticket.
          <ZimmProductContent
            name={info.name}
            headingLevel="h2"
            // The base header gates its price and its promo together behind the same
            // `!isProductPartOfBundle` check. The promo is gated below; without this the
            // price would be the one part of that header which stopped being gated.
            currentPrice={isProductPartOfBundle ? undefined : info.price}
            originalPrice={isProductPartOfBundle ? undefined : info.wasPrice}
            isPriceLoading={isPriceLoading}
            description={info.description}
          />
        )}
      </Skeleton>

      {!isProductPartOfBundle && (
        <Skeleton isLoaded={Boolean(headerProduct)}>
          {headerProduct?.productPromotions && <PromoCallout product={headerProduct} />}
        </Skeleton>
      )}
    </VStack>
  );
};

